mapper.select:
SELECT NVL(MAX(exercise_order), 0) + 1
FROM routine_exercises
WHERE routine_id = #{routineId}

mapper.insert:
INSERT INTO routine_exercises (
    routine_exercise_id, routine_id, exercise_id, exercise_order, memo
)
VALUES (
    SEQ_ROUTINE_EXERCISES.NEXTVAL,
    #{routineId},
    #{exerciseId},
    #{exerciseOrder},
    #{memo,jdbcType=VARCHAR}
)

mapper.delete:
DELETE FROM routine_exercises
WHERE routine_exercise_id = #{routineExerciseId}
  AND routine_id = #{routineId}
  AND EXISTS (
      SELECT 1
      FROM routines r
      WHERE r.routine_id = routine_exercises.routine_id
        AND r.member_id = #{memberId}
  )
